-- ── story 4-7a: returns disposition ──────────────────────────────────────
-- Generated by drizzle-kit (the two tables, the column and the indexes) and
-- hand-amended around the generated part: the fail-fast guard, the
-- pre-flight, the backfill and its proof, `IF NOT EXISTS` on every table and
-- index (guide §3, linted from 0089 on), the CHECKs, the RLS policies, the
-- `qc_holds_kind_check` widening and the post-migration probe (drizzle-kit is
-- blind to CHECKs and RLS; `bun run db:generate` afterwards reports "No
-- schema changes").
--
-- 1. `return_receipt_lines.open_qty bigint NOT NULL DEFAULT 0` (A1) — the
--    milli-units of a received line still awaiting a disposition. Backfilled
--    `= qty`: no disposition exists before this migration, so every received
--    unit is awaiting. The backfill is PROVED (a RAISE on any mismatch), and
--    CHECK `0 ≤ open_qty ≤ qty` backstops every later write.
-- 2. `return_dispositions` — one row per disposition (restock | quarantine |
--    scrap) of a receipt line or part of one. Append-only.
-- 3. `return_hold_settlements` — one row per closed return hold, written by
--    the returns hold-settlement subscriber. Append-only.
-- 4. `qc_holds_kind_check` widens to `manual | receipt | return` (DROP and
--    re-ADD, guide §4). `qc_holds_kind_pairing` (0078) needs no change: a
--    return hold names no GRN line. `qc_holds_status_check` is 0091's and is
--    not touched.
--
-- Lock cost (A10):
--   * `return_receipt_lines` grows with return volume, far below the ledger.
--     The ADD COLUMN with a constant default is metadata-only; the backfill
--     UPDATE rewrites each row once under row locks; the `open_qty` CHECK is
--     added VALID — the migrator runs the pending set in ONE transaction, so a
--     separate VALIDATE would scan under the same ACCESS EXCLUSIVE anyway.
--   * `qc_holds` holds one row per quarantine decision — small by
--     construction — so the re-added kind CHECK is VALID (0091's reasoning);
--     it scans the table once under ACCESS EXCLUSIVE.
--   * The two new tables are empty: their indexes and CHECKs cost nothing.
-- The deploy migrator sets `lock_timeout` (MIGRATE_LOCK_TIMEOUT_MS, default
-- 5 s): a lock it cannot take fails the deploy cleanly and the pending set
-- rolls back whole (DEPLOY.md §5).

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'return_dispositions'
	) THEN
		RAISE EXCEPTION 'migration 0097: return_dispositions already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
-- ── 1. pre-flight: every QC hold kind is one the widened CHECK admits ────
-- The re-added CHECK would abort the deploy on an unknown kind; list every
-- offender at once instead.
DO $$
DECLARE
	offenders text;
BEGIN
	SELECT string_agg(format('tenant %s hold %s (kind %s)', "tenant_id", "id", "kind"), '; ' ORDER BY "tenant_id", "id")
	  INTO offenders
	  FROM "qc_holds"
	 WHERE "kind" NOT IN ('manual', 'receipt');
	IF offenders IS NOT NULL THEN
		RAISE EXCEPTION 'migration 0097: QC holds of an unknown kind — fix each before deploying: %', offenders;
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "return_dispositions" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"warehouse_id" uuid NOT NULL,
	"return_receipt_id" uuid NOT NULL,
	"return_receipt_line_id" uuid NOT NULL,
	"rma_id" uuid NOT NULL,
	"sku_id" uuid NOT NULL,
	"outcome" text NOT NULL,
	"qty" bigint NOT NULL,
	"batch_id" uuid,
	"serial_id" uuid,
	"handling_unit_id" uuid,
	"to_bin_id" uuid,
	"qc_hold_id" uuid,
	"reason_code" text,
	"note" text,
	"device_id" uuid,
	"decided_by" uuid NOT NULL,
	"ledger_event_id" uuid,
	"occurred_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	-- ── hand-amended: the CHECKs (migration SQL only) ───────────────────
	-- `outcome` is NOT NULL, so `IN` cannot pass a NULL; the nullable
	-- `reason_code` says `IS NOT NULL` before its `IN` (guide §3). Mirrored by
	-- RETURN_DISPOSITION_OUTCOMES / RETURN_DISPOSITION_REASONS
	-- (returns/return-disposition.command.ts), pinned by
	-- test/return-dispositions.spec.ts.
	CONSTRAINT "return_dispositions_outcome_check" CHECK ("outcome" IN ('restock','quarantine','scrap')),
	CONSTRAINT "return_dispositions_qty_positive" CHECK ("qty" > 0),
	-- A serial or a returned case is exactly one unit (1,000 milli-units), and
	-- a unit is one or the other, never both.
	CONSTRAINT "return_dispositions_identity_shape" CHECK (
		("serial_id" IS NULL OR "handling_unit_id" IS NULL)
		AND ("serial_id" IS NULL OR "qty" = 1000)
		AND ("handling_unit_id" IS NULL OR "qty" = 1000)
	),
	-- Restock: a target bin, no reason, no note, no hold. Quarantine: a hold
	-- and a reason, no bin, no unit identity (QC holds carry neither — 4-7a
	-- decision 5). Scrap: a reason, no bin, no hold. A device only restocks.
	CONSTRAINT "return_dispositions_outcome_shape" CHECK (
		("outcome" = 'restock' AND "to_bin_id" IS NOT NULL AND "qc_hold_id" IS NULL AND "reason_code" IS NULL AND "note" IS NULL)
		OR ("outcome" = 'quarantine' AND "to_bin_id" IS NULL AND "qc_hold_id" IS NOT NULL AND "reason_code" IS NOT NULL
			AND "serial_id" IS NULL AND "handling_unit_id" IS NULL AND "device_id" IS NULL)
		OR ("outcome" = 'scrap' AND "to_bin_id" IS NULL AND "qc_hold_id" IS NULL AND "reason_code" IS NOT NULL AND "device_id" IS NULL)
	),
	CONSTRAINT "return_dispositions_reason_check" CHECK (
		"reason_code" IS NULL
		OR ("reason_code" IS NOT NULL AND "reason_code" IN ('damaged','defective','expired','missing-parts','contaminated','needs-inspection','client-instruction','other'))
	),
	CONSTRAINT "return_dispositions_note_check" CHECK (
		("note" IS NULL OR (char_length("note") BETWEEN 1 AND 200 AND "note" = btrim("note")))
		AND ("reason_code" IS DISTINCT FROM 'other' OR "note" IS NOT NULL)
	),
	-- The ledger event is the restock's / scrap's own; a quarantine's
	-- `qc.held` belongs to QC (linked by `qc_hold_id`).
	CONSTRAINT "return_dispositions_ledger_event_pairing" CHECK (
		("ledger_event_id" IS NOT NULL) = ("outcome" IN ('restock','scrap'))
	)
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "return_hold_settlements" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"disposition_id" uuid NOT NULL,
	"qc_hold_id" uuid NOT NULL,
	"status" text NOT NULL,
	"held_qty" bigint NOT NULL,
	"returned_qty" bigint NOT NULL,
	"failed_qty" bigint NOT NULL,
	"settled_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	-- ── hand-amended: the CHECKs ─────────────────────────────────────────
	CONSTRAINT "return_hold_settlements_status_check" CHECK ("status" IN ('released','inspected')),
	CONSTRAINT "return_hold_settlements_qty_check" CHECK (
		"held_qty" > 0 AND "returned_qty" >= 0 AND "failed_qty" >= 0 AND "returned_qty" + "failed_qty" = "held_qty"
	),
	-- A release returns everything; only an inspection can fail units.
	CONSTRAINT "return_hold_settlements_release_shape" CHECK ("status" <> 'released' OR "failed_qty" = 0)
);
--> statement-breakpoint
-- ── 2. the open quantity, backfilled and proved (A1) ─────────────────────
ALTER TABLE "return_receipt_lines" ADD COLUMN "open_qty" bigint DEFAULT 0 NOT NULL;--> statement-breakpoint
UPDATE "return_receipt_lines" SET "open_qty" = "qty";--> statement-breakpoint
DO $$
DECLARE
	mismatched bigint;
BEGIN
	SELECT count(*) INTO mismatched FROM "return_receipt_lines" WHERE "open_qty" <> "qty";
	IF mismatched <> 0 THEN
		RAISE EXCEPTION 'migration 0097: % return receipt line(s) did not backfill open_qty = qty.', mismatched;
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "return_receipt_lines" ADD CONSTRAINT "return_receipt_lines_open_qty_range"
	CHECK ("open_qty" >= 0 AND "open_qty" <= "qty");--> statement-breakpoint
-- ── 3. the indexes (IF NOT EXISTS — guide §3) ────────────────────────────
CREATE INDEX IF NOT EXISTS "return_dispositions_tenant_line_idx" ON "return_dispositions" USING btree ("tenant_id","return_receipt_line_id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "return_dispositions_tenant_rma_idx" ON "return_dispositions" USING btree ("tenant_id","rma_id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "return_dispositions_tenant_client_created_idx" ON "return_dispositions" USING btree ("tenant_id","client_id","created_at","id");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "return_dispositions_tenant_hold_unique" ON "return_dispositions" USING btree ("tenant_id","qc_hold_id") WHERE "return_dispositions"."qc_hold_id" IS NOT NULL;--> statement-breakpoint
-- Per RECEIPT LINE (4-7b's fix to the 4-7a design, applied at code time): a
-- serial restocked, re-sold and returned again arrives on a NEW receipt line
-- and must be dispositionable again. A quarantine names no serial.
CREATE UNIQUE INDEX IF NOT EXISTS "return_dispositions_tenant_line_serial_unique" ON "return_dispositions" USING btree ("tenant_id","return_receipt_line_id","serial_id") WHERE "return_dispositions"."serial_id" IS NOT NULL AND "return_dispositions"."outcome" <> 'quarantine';--> statement-breakpoint
-- A returned case is a NEW handling unit per receipt line (13-2), so it is
-- dispositioned at most once.
CREATE UNIQUE INDEX IF NOT EXISTS "return_dispositions_tenant_handling_unit_unique" ON "return_dispositions" USING btree ("tenant_id","handling_unit_id") WHERE "return_dispositions"."handling_unit_id" IS NOT NULL;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "return_hold_settlements_tenant_hold_unique" ON "return_hold_settlements" USING btree ("tenant_id","qc_hold_id");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "return_hold_settlements_tenant_disposition_unique" ON "return_hold_settlements" USING btree ("tenant_id","disposition_id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "return_receipt_lines_tenant_open_idx" ON "return_receipt_lines" USING btree ("tenant_id","created_at","id") WHERE "return_receipt_lines"."open_qty" > 0;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "return_receipt_lines_tenant_sku_batch_open_idx" ON "return_receipt_lines" USING btree ("tenant_id","sku_id","batch_id","created_at","id") WHERE "return_receipt_lines"."open_qty" > 0;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "return_receipt_lines_tenant_serial_idx" ON "return_receipt_lines" USING btree ("tenant_id","serial_id") WHERE "return_receipt_lines"."serial_id" IS NOT NULL;--> statement-breakpoint
-- ── 4. the QC hold kind widens (DROP then re-ADD — guide §4) ─────────────
-- Mirrors `QC_HOLD_KINDS` (inbound/qc.command.ts), pinned against this
-- constraint by test/return-dispositions.spec.ts.
ALTER TABLE "qc_holds" DROP CONSTRAINT "qc_holds_kind_check";--> statement-breakpoint
ALTER TABLE "qc_holds" ADD CONSTRAINT "qc_holds_kind_check" CHECK (
	"kind" IN ('manual', 'receipt', 'return')
);--> statement-breakpoint
-- ── 5. RLS — the `return_receipts` tenant + client shape (0073) ──────────
ALTER TABLE "return_dispositions" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "return_hold_settlements" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "return_dispositions_tenant_isolation" ON "return_dispositions"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	);--> statement-breakpoint
CREATE POLICY "return_hold_settlements_tenant_isolation" ON "return_hold_settlements"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	);--> statement-breakpoint
-- ── 6. the post-migration assertion (the 0073 / 0092 / 0096 model) ───────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refuses everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT (CHECKs and partial uniques alike).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	l uuid := gen_random_uuid();
	s uuid := gen_random_uuid();
	h uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: one per outcome (a batch restock, a serial
	-- restock, a device restock, a quarantine, a scrap with a note, a case
	-- scrap), a settlement of each status, a `return` hold, and a receipt
	-- line at both ends of its open range.
	BEGIN
		INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","batch_id","serial_id","handling_unit_id","to_bin_id","qc_hold_id","reason_code","note","device_id","decided_by","ledger_event_id","occurred_at")
		VALUES
			(gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 2500, t, NULL, NULL, t, NULL, NULL, NULL, NULL, t, gen_random_uuid(), now()),
			(gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 1000, NULL, s, NULL, t, NULL, NULL, NULL, t, t, gen_random_uuid(), now()),
			(gen_random_uuid(), t, c, t, t, l, t, t, 'quarantine', 3000, t, NULL, NULL, NULL, h, 'needs-inspection', NULL, NULL, t, NULL, now()),
			(gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 500, NULL, NULL, NULL, NULL, NULL, 'other', 'crushed in transit', NULL, t, gen_random_uuid(), now()),
			(gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 1000, NULL, NULL, u, NULL, NULL, 'damaged', NULL, NULL, t, gen_random_uuid(), now());
		-- The same serial again on ANOTHER receipt line (a second return): accepted.
		INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","serial_id","to_bin_id","decided_by","ledger_event_id","occurred_at")
		VALUES (gen_random_uuid(), t, c, t, t, gen_random_uuid(), t, t, 'restock', 1000, s, t, t, gen_random_uuid(), now());
		INSERT INTO "return_hold_settlements" ("id","tenant_id","client_id","disposition_id","qc_hold_id","status","held_qty","returned_qty","failed_qty","settled_at")
		VALUES
			(gen_random_uuid(), t, c, gen_random_uuid(), h, 'inspected', 3000, 1000, 2000, now()),
			(gen_random_uuid(), t, c, gen_random_uuid(), gen_random_uuid(), 'released', 2000, 2000, 0, now());
		INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at","kind")
		VALUES (gen_random_uuid(), t, t, t, t, 'return RMA-0001 · needs-inspection', 'open', t, now(), 'return');
		INSERT INTO "return_receipt_lines" ("id","tenant_id","return_receipt_id","rma_line_id","sku_id","line_no","qty","condition","ledger_event_id","open_qty")
		VALUES (gen_random_uuid(), t, t, t, t, 1, 2000, 'resaleable', t, 2000),
		       (gen_random_uuid(), t, t, t, t, 2, 2000, 'damaged', t, 0);
		RAISE EXCEPTION USING ERRCODE = 'P0097', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN SQLSTATE 'P0097' THEN NULL;
	END;
	-- (2) the refused shapes, each naming the constraint that must refuse it.
	FOREACH probe IN ARRAY ARRAY[
		'unknown outcome',
		'zero qty',
		'serial and case',
		'serial of two units',
		'case of two units',
		'restock without a bin',
		'restock with a reason',
		'restock with a note',
		'quarantine without a hold',
		'quarantine of a serial',
		'quarantine by a device',
		'scrap without a reason',
		'scrap by a device',
		'restock with a hold',
		'scrap with a bin',
		'scrap with a hold',
		'quarantine with a bin',
		'quarantine of a case',
		'unknown reason',
		'other without a note',
		'blank note',
		'untrimmed note',
		'restock without a ledger event',
		'quarantine with a ledger event',
		'same serial twice on one line',
		'same case twice',
		'two dispositions of one hold',
		'unknown settlement status',
		'settlement that does not add up',
		'release that failed units',
		'zero settlement',
		'two settlements of one hold',
		'two settlements of one disposition',
		'open above received',
		'negative open',
		'unknown hold kind'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown outcome' THEN 'return_dispositions_outcome_check'
			WHEN 'zero qty' THEN 'return_dispositions_qty_positive'
			WHEN 'serial and case' THEN 'return_dispositions_identity_shape'
			WHEN 'serial of two units' THEN 'return_dispositions_identity_shape'
			WHEN 'case of two units' THEN 'return_dispositions_identity_shape'
			WHEN 'restock without a bin' THEN 'return_dispositions_outcome_shape'
			WHEN 'restock with a reason' THEN 'return_dispositions_outcome_shape'
			WHEN 'restock with a note' THEN 'return_dispositions_outcome_shape'
			WHEN 'quarantine without a hold' THEN 'return_dispositions_outcome_shape'
			WHEN 'quarantine of a serial' THEN 'return_dispositions_outcome_shape'
			WHEN 'quarantine by a device' THEN 'return_dispositions_outcome_shape'
			WHEN 'scrap without a reason' THEN 'return_dispositions_outcome_shape'
			WHEN 'scrap by a device' THEN 'return_dispositions_outcome_shape'
			WHEN 'restock with a hold' THEN 'return_dispositions_outcome_shape'
			WHEN 'scrap with a bin' THEN 'return_dispositions_outcome_shape'
			WHEN 'scrap with a hold' THEN 'return_dispositions_outcome_shape'
			WHEN 'quarantine with a bin' THEN 'return_dispositions_outcome_shape'
			WHEN 'quarantine of a case' THEN 'return_dispositions_outcome_shape'
			WHEN 'unknown reason' THEN 'return_dispositions_reason_check'
			WHEN 'other without a note' THEN 'return_dispositions_note_check'
			WHEN 'blank note' THEN 'return_dispositions_note_check'
			WHEN 'untrimmed note' THEN 'return_dispositions_note_check'
			WHEN 'restock without a ledger event' THEN 'return_dispositions_ledger_event_pairing'
			WHEN 'quarantine with a ledger event' THEN 'return_dispositions_ledger_event_pairing'
			WHEN 'same serial twice on one line' THEN 'return_dispositions_tenant_line_serial_unique'
			WHEN 'same case twice' THEN 'return_dispositions_tenant_handling_unit_unique'
			WHEN 'two dispositions of one hold' THEN 'return_dispositions_tenant_hold_unique'
			WHEN 'unknown settlement status' THEN 'return_hold_settlements_status_check'
			WHEN 'settlement that does not add up' THEN 'return_hold_settlements_qty_check'
			WHEN 'release that failed units' THEN 'return_hold_settlements_release_shape'
			WHEN 'zero settlement' THEN 'return_hold_settlements_qty_check'
			WHEN 'two settlements of one hold' THEN 'return_hold_settlements_tenant_hold_unique'
			WHEN 'two settlements of one disposition' THEN 'return_hold_settlements_tenant_disposition_unique'
			WHEN 'open above received' THEN 'return_receipt_lines_open_qty_range'
			WHEN 'negative open' THEN 'return_receipt_lines_open_qty_range'
			ELSE 'qc_holds_kind_check'
		END;
		BEGIN
			CASE probe
				WHEN 'unknown outcome' THEN
					-- No ledger event, so only the vocabulary CHECK can refuse it
					-- (CHECKs run in name order — `ledger_event_pairing` first).
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","to_bin_id","decided_by","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'return-to-client', 1000, t, t, now());
				WHEN 'zero qty' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","to_bin_id","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 0, t, t, t, now());
				WHEN 'serial and case' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","serial_id","handling_unit_id","to_bin_id","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 1000, gen_random_uuid(), gen_random_uuid(), t, t, t, now());
				WHEN 'serial of two units' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","serial_id","to_bin_id","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 2000, gen_random_uuid(), t, t, t, now());
				WHEN 'case of two units' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","handling_unit_id","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 2000, gen_random_uuid(), 'damaged', t, t, now());
				WHEN 'restock without a bin' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 1000, t, t, now());
				WHEN 'restock with a reason' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","to_bin_id","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 1000, t, 'damaged', t, t, now());
				WHEN 'restock with a note' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","to_bin_id","note","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 1000, t, 'looks fine', t, t, now());
				WHEN 'quarantine without a hold' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","reason_code","decided_by","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'quarantine', 1000, 'damaged', t, now());
				WHEN 'quarantine of a serial' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","serial_id","qc_hold_id","reason_code","decided_by","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'quarantine', 1000, gen_random_uuid(), gen_random_uuid(), 'damaged', t, now());
				WHEN 'quarantine by a device' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","qc_hold_id","reason_code","device_id","decided_by","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'quarantine', 1000, gen_random_uuid(), 'damaged', t, t, now());
				WHEN 'scrap without a reason' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 1000, t, t, now());
				WHEN 'scrap by a device' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","reason_code","device_id","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 1000, 'damaged', t, t, t, now());
				WHEN 'restock with a hold' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","handling_unit_id","to_bin_id","qc_hold_id","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 1000, NULL, t, gen_random_uuid(), NULL, t, t, now());
				WHEN 'scrap with a bin' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","handling_unit_id","to_bin_id","qc_hold_id","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 1000, NULL, t, NULL, 'damaged', t, t, now());
				WHEN 'scrap with a hold' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","handling_unit_id","to_bin_id","qc_hold_id","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 1000, NULL, NULL, gen_random_uuid(), 'damaged', t, t, now());
				WHEN 'quarantine with a bin' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","handling_unit_id","to_bin_id","qc_hold_id","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'quarantine', 1000, NULL, t, gen_random_uuid(), 'damaged', t, NULL, now());
				WHEN 'quarantine of a case' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","handling_unit_id","to_bin_id","qc_hold_id","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'quarantine', 1000, gen_random_uuid(), NULL, gen_random_uuid(), 'damaged', t, NULL, now());
				WHEN 'unknown reason' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 1000, 'lost', t, t, now());
				WHEN 'other without a note' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 1000, 'other', t, t, now());
				WHEN 'blank note' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","reason_code","note","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 1000, 'damaged', '', t, t, now());
				WHEN 'untrimmed note' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","reason_code","note","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 1000, 'damaged', ' padded ', t, t, now());
				WHEN 'restock without a ledger event' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","to_bin_id","decided_by","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 1000, t, t, now());
				WHEN 'quarantine with a ledger event' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","qc_hold_id","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'quarantine', 1000, gen_random_uuid(), 'damaged', t, t, now());
				WHEN 'same serial twice on one line' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","serial_id","to_bin_id","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 1000, s, t, NULL, t, t, now()),
					       (gen_random_uuid(), t, c, t, t, l, t, t, 'scrap', 1000, s, NULL, 'damaged', t, t, now());
				WHEN 'same case twice' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","handling_unit_id","to_bin_id","reason_code","decided_by","ledger_event_id","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'restock', 1000, u, t, NULL, t, t, now()),
					       (gen_random_uuid(), t, c, t, t, gen_random_uuid(), t, t, 'scrap', 1000, u, NULL, 'damaged', t, t, now());
				WHEN 'two dispositions of one hold' THEN
					INSERT INTO "return_dispositions" ("id","tenant_id","client_id","warehouse_id","return_receipt_id","return_receipt_line_id","rma_id","sku_id","outcome","qty","qc_hold_id","reason_code","decided_by","occurred_at")
					VALUES (gen_random_uuid(), t, c, t, t, l, t, t, 'quarantine', 1000, h, 'damaged', t, now()),
					       (gen_random_uuid(), t, c, t, t, l, t, t, 'quarantine', 1000, h, 'damaged', t, now());
				WHEN 'unknown settlement status' THEN
					INSERT INTO "return_hold_settlements" ("id","tenant_id","client_id","disposition_id","qc_hold_id","status","held_qty","returned_qty","failed_qty","settled_at")
					VALUES (gen_random_uuid(), t, c, gen_random_uuid(), gen_random_uuid(), 'open', 1000, 1000, 0, now());
				WHEN 'settlement that does not add up' THEN
					INSERT INTO "return_hold_settlements" ("id","tenant_id","client_id","disposition_id","qc_hold_id","status","held_qty","returned_qty","failed_qty","settled_at")
					VALUES (gen_random_uuid(), t, c, gen_random_uuid(), gen_random_uuid(), 'inspected', 3000, 1000, 1000, now());
				WHEN 'release that failed units' THEN
					INSERT INTO "return_hold_settlements" ("id","tenant_id","client_id","disposition_id","qc_hold_id","status","held_qty","returned_qty","failed_qty","settled_at")
					VALUES (gen_random_uuid(), t, c, gen_random_uuid(), gen_random_uuid(), 'released', 2000, 1000, 1000, now());
				WHEN 'zero settlement' THEN
					INSERT INTO "return_hold_settlements" ("id","tenant_id","client_id","disposition_id","qc_hold_id","status","held_qty","returned_qty","failed_qty","settled_at")
					VALUES (gen_random_uuid(), t, c, gen_random_uuid(), gen_random_uuid(), 'released', 0, 0, 0, now());
				WHEN 'two settlements of one hold' THEN
					INSERT INTO "return_hold_settlements" ("id","tenant_id","client_id","disposition_id","qc_hold_id","status","held_qty","returned_qty","failed_qty","settled_at")
					VALUES (gen_random_uuid(), t, c, gen_random_uuid(), h, 'released', 1000, 1000, 0, now()),
					       (gen_random_uuid(), t, c, gen_random_uuid(), h, 'released', 1000, 1000, 0, now());
				WHEN 'two settlements of one disposition' THEN
					INSERT INTO "return_hold_settlements" ("id","tenant_id","client_id","disposition_id","qc_hold_id","status","held_qty","returned_qty","failed_qty","settled_at")
					VALUES (gen_random_uuid(), t, c, l, gen_random_uuid(), 'released', 1000, 1000, 0, now()),
					       (gen_random_uuid(), t, c, l, gen_random_uuid(), 'released', 1000, 1000, 0, now());
				WHEN 'open above received' THEN
					INSERT INTO "return_receipt_lines" ("id","tenant_id","return_receipt_id","rma_line_id","sku_id","line_no","qty","condition","ledger_event_id","open_qty")
					VALUES (gen_random_uuid(), t, t, t, t, 1, 1000, 'resaleable', t, 2000);
				WHEN 'negative open' THEN
					INSERT INTO "return_receipt_lines" ("id","tenant_id","return_receipt_id","rma_line_id","sku_id","line_no","qty","condition","ledger_event_id","open_qty")
					VALUES (gen_random_uuid(), t, t, t, t, 1, 1000, 'resaleable', t, -1);
				WHEN 'unknown hold kind' THEN
					INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at","kind")
					VALUES (gen_random_uuid(), t, t, t, t, 'probe', 'open', t, now(), 'returned');
			END CASE;
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0097: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "return_dispositions" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "return_hold_settlements" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "qc_holds" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "return_receipt_lines" WHERE "tenant_id" = t)
	THEN
		RAISE EXCEPTION 'migration 0097: a probe row survived.';
	END IF;
END $$;
